INSERT INTO subjects (id, name, icon, color, description) VALUES
  ('tic2', 'Tecnologías de la Información y Comunicación II', '💻', '#0073aa', '2º Bachillerato — Desarrollo web, ciberseguridad, programación y metodologías ágiles'),
  ('cyr', 'Computación y Robótica', '🤖', '#6c63ff', '1º a 3º ESO — Alfabetización digital, programación por bloques, robótica, IA y ciberseguridad')
INSERT INTO guilds (id, subject_id, name, icon, color, image_url, description) VALUES
  ('turing', 'tic2', 'La Hermandad de Turing', '🗝️', '#8e44ad', 'img/turing.png', 'Herederos del mismísimo Alan Turing. Maestros de la lógica y la criptografía. Su objetivo es descifrar los secretos mejor guardados del ciberespacio.'),
  ('lovelace', 'tic2', 'Los Hijos de Lovelace', '⚙️', '#2980b9', 'img/lovelace.png', 'Bajo el manto de Ada Lovelace, la primera programadora de la historia. Son los arquitectos del código, estructurados, analíticos y elegantes.'),
  ('hopper', 'tic2', 'El Escuadrón de Hopper', '🐛', '#16a085', 'img/hopper.png', 'Inspirados en Grace Hopper. Compiladores natos, depuradores incansables y siempre listos para encontrar y aplastar cualquier "bug" en el código.'),
  ('stallman', 'tic2', 'La Resistencia de Stallman', '🐃', '#e67e22', 'img/stallman.png', 'Devotos del Software Libre y herederos de la filosofía GNU de Richard Stallman. Luchan por la libertad del código y el conocimiento sin cadenas.')
INSERT INTO guilds (id, subject_id, name, icon, color, image_url, description) VALUES
  ('r2d2', 'cyr', 'La Brigada R2-D2', '🔵', '#00bcd4', 'img/gremios/r2d2.png', 'Fieles, valientes y siempre listos para la misión. Inspirados en el famoso astromecánico de Star Wars, esta brigada destaca por su lealtad y su capacidad para resolver problemas en los momentos más críticos.'),
  ('walle', 'cyr', 'El Colectivo WALL·E', '🟠', '#ff9800', 'img/gremios/walle.png', 'Curiosos, creativos y con un enorme corazón. Como el robot de Pixar, este colectivo valora la creatividad por encima de todo y cree que incluso la tarea más pequeña puede cambiar el mundo.'),
  ('baymax', 'cyr', 'La Unidad Baymax', '🤍', '#e53935', 'img/gremios/baymax.png', 'Pacíficos, empáticos y siempre dispuestos a ayudar. Inspirados en el robot asistente médico, los miembros de esta unidad destacan por su compañerismo y su capacidad para sanar los errores del código en equipo.'),
  ('terminator', 'cyr', 'La Orden Terminator', '💀', '#607d8b', 'img/gremios/terminator.png', 'Imparables, determinados y forjados en acero. Como el T-800, los miembros de esta orden no conocen el abandono. Una vez que se proponen un objetivo, nada ni nadie puede detenerlos.')
